import itertools

# K_5 vertices: 0,1,2,3,4
# Edges in lexicographic order of (i,j) for i<j
edges = [(i,j) for i in range(5) for j in range(i+1,5)]
print("Edge indices:")
for idx, (i,j) in enumerate(edges):
    print(f"  c[{idx}] = edge ({i},{j})")

# Fixed: c[3]=1, c[9]=0
# c[3] is edge (0,4) = blue
# c[9] is edge (3,4) = red

fixed = {3: 1, 9: 0}

# Check all 2^10 = 1024 colorings
found = False
solutions = []
for bits in itertools.product([0,1], repeat=10):
    # Check fixed
    ok = True
    for idx, val in fixed.items():
        if bits[idx] != val:
            ok = False
            break
    if not ok:
        continue

    # Build adjacency for each color
    red_edges = set()
    blue_edges = set()
    for idx, (i,j) in enumerate(edges):
        if bits[idx] == 0:
            red_edges.add((i,j))
        else:
            blue_edges.add((i,j))

    # Check for red triangle
    red_triangle = False
    for i in range(5):
        for j in range(i+1,5):
            for k in range(j+1,5):
                if (i,j) in red_edges and (i,k) in red_edges and (j,k) in red_edges:
                    red_triangle = True
                    break
            if red_triangle:
                break
        if red_triangle:
            break

    # Check for blue triangle
    blue_triangle = False
    for i in range(5):
        for j in range(i+1,5):
            for k in range(j+1,5):
                if (i,j) in blue_edges and (i,k) in blue_edges and (j,k) in blue_edges:
                    blue_triangle = True
                    break
            if blue_triangle:
                break
        if blue_triangle:
            break

    if not red_triangle and not blue_triangle:
        solutions.append(list(bits))

print(f"Found {len(solutions)} solutions")
for sol in solutions:
    print(f"  {sol}")
    # Show the coloring
    for idx, (i,j) in enumerate(edges):
        color = "red" if sol[idx]==0 else "blue"
        print(f"    ({i},{j}) = {color}")
    print()

